444	    private static final class CountingInputStream extends FilterInputStream {
445	        int count = 0;
446	
447	        CountingInputStream(InputStream in) {
448	            super(in);
449	        }
450	
451	        @Override
452	        public int read(byte[] b, int off, int len) throws IOException {
453	            int r = super.read(b, off, len);
454	            if (r > 0) count += r;
455	            return r;
456	        }
457	
458	        @Override
459	        public int read() throws IOException {
460	            int r = super.read();
461	            if (r != -1) count++;
462	            return r;
463	        }
464	    }
