466	    /** delivers {@code failAfter} zero bytes, then raises an IOException */
467	    private static final class FailingInputStream extends InputStream {
468	        private int remaining;
469	
470	        FailingInputStream(int failAfter) {
471	            this.remaining = failAfter;
472	        }
473	
474	        @Override
475	        public int read(byte[] b, int off, int len) throws IOException {
476	            if (remaining <= 0) throw new IOException("boom");
477	            int read = Math.min(remaining, len);
478	            remaining -= read;
479	            return read;
480	        }
481	
482	        @Override
483	        public int read() throws IOException {
484	            if (remaining <= 0) throw new IOException("boom");
485	            remaining--;
486	            return 0;
487	        }
488	    }
489	
490	    private static final class VirtualInputStream extends InputStream {
491	        private long remaining;
492	
493	        VirtualInputStream(long size) {
494	            remaining = size;
495	        }
496	
497	        @Override
498	        public int read() {
499	            if (remaining == 0) return -1;
500	            remaining--;
501	            return 0;
502	        }
503	
504	        @Override
505	        public int read(byte[] bytes, int offset, int length) {
506	            if (remaining == 0) return -1;
507	            int read = (int) Math.min(remaining, length);
508	            remaining -= read;
509	            return read;
510	        }
511	    }
