1365	    /** records progress events for a single logical request and validates their shape */
1366	    static final class ProgressTracker implements Progress<Connection.Response> {
1367	        static final class Event {
1368	            final int processed, total;
1369	            final float percent;
1370	            Event(int processed, int total, float percent) {
1371	                this.processed = processed;
1372	                this.total = total;
1373	                this.percent = percent;
1374	            }
1375	        }
1376	
1377	        final List<Event> events = new ArrayList<>();
1378	        Connection.Response context;
1379	
1380	        @Override public void onProgress(int processed, int total, float percent, Connection.Response response) {
1381	            if (!events.isEmpty()) {
1382	                Event prev = events.get(events.size() - 1);
1383	                assertTrue(processed >= prev.processed, "processed regressed: " + prev.processed + " -> " + processed);
1384	                assertTrue(percent >= prev.percent, "percent regressed: " + prev.percent + " -> " + percent);
1385	            }
1386	            assertTrue(percent >= 0f && percent <= 100f);
1387	            events.add(new Event(processed, total, percent));
1388	            context = response;
1389	        }
1390	
1391	        int completions() {
1392	            return (int) events.stream().filter(e -> e.percent == 100f).count();
1393	        }
1394	
1395	        void assertCompletedOnce(int expectedProcessed) {
1396	            assertEquals(1, completions(), "exactly one completion event, events=" + events);
1397	            Event last = events.get(events.size() - 1);
1398	            assertEquals(100f, last.percent);
1399	            assertEquals(expectedProcessed, last.processed);
1400	            assertEquals(expectedProcessed, last.total);
1401	        }
1402	    }
