16	import java.net.http.HttpRequest;
17	import java.net.http.HttpResponse;
18	import java.security.NoSuchAlgorithmException;
19	import java.time.Duration;
20	import java.util.ArrayList;
21	import java.util.Collections;
22	import java.util.List;
23	import java.util.concurrent.atomic.AtomicReference;
24	
25	import javax.net.ssl.SSLContext;
26	
27	import static org.jsoup.helper.HttpConnection.Response;
28	import static org.jsoup.helper.HttpConnection.Response.writePost;
29	
30	/**
31	 Executes requests using the HttpClient, for http/2 support. Enabled by default when available. To disable, set
32	 property {@code jsoup.useHttpClient} to {@code false}.
33	 */
34	class HttpClientExecutor extends RequestExecutor {
35	    private static final Object SharedClientLock = new Object();
36	    private static volatile @Nullable ClientState sharedClientState;
37	
38	    // HttpClient expects proxy settings per client; jsoup supports them per request, so resolve them from the calling
39	    // thread.
40	    static ThreadLocal<@Nullable Proxy> perRequestProxy = new ThreadLocal<>();
41	
42	    @Nullable
43	    HttpResponse<InputStream> hRes;
44	
45	    public HttpClientExecutor(HttpConnection.Request request, HttpConnection.@Nullable Response previousResponse) {
46	        super(request, previousResponse);
47	    }
48	
49	    /**
50	     Returns the shared client for default requests, or the owning connection's configured client.
51	     */
52	    HttpClient client() {
53	        RequestAuthenticator auth = req.authenticator;
54	        // HttpClient captures the JVM default SSL context when built, and that default can change at runtime.
55	        SSLContext sslContext = req.sslContext != null ? req.sslContext : defaultSslContext();
56	        if (auth == null && req.sslContext == null) return sharedClient(sslContext);
57	        return configuredClient(auth, sslContext);
58	    }
59	
60	    private HttpClient configuredClient(@Nullable RequestAuthenticator auth, SSLContext sslContext) {
61	        ClientState state = (ClientState) req.connection.clientState;
62	        if (state != null && state.matches(auth, sslContext)) return state.client;
63	        synchronized (req.connection) {
64	            // another request may have initialized this connection's client while we waited for the lock.
65	            state = (ClientState) req.connection.clientState;
66	            if (state == null || !state.matches(auth, sslContext)) {
67	                state = new ClientState(auth, sslContext);
68	                req.connection.clientState = state;
69	            }
70	            return state.client;
71	        }
72	    }
73	
74	    private static HttpClient sharedClient(SSLContext sslContext) {
75	        ClientState state = sharedClientState;
76	        if (state != null && state.matches(null, sslContext)) return state.client;
77	        synchronized (SharedClientLock) {
78	            state = sharedClientState;
79	            if (state != null && state.matches(null, sslContext)) return state.client;
80	            state = new ClientState(null, sslContext);
81	            sharedClientState = state;
82	            return state.client;
83	        }
84	    }
85	
86	    private static HttpClient newClient(@Nullable RequestAuthenticator authenticator, SSLContext sslContext) {
87	        HttpClient.Builder builder = HttpClient.newBuilder();
88	        builder.followRedirects(HttpClient.Redirect.NEVER); // customized redirects
89	        builder.proxy(new ProxyWrap()); // thread local impl for per request; called on executing thread
90	        if (authenticator != null) builder.authenticator(new AuthenticationHandler(authenticator));
91	        builder.sslContext(sslContext);
92	        return builder.build();
93	    }
94	
95	    private static SSLContext defaultSslContext() {
96	        try {
97	            return SSLContext.getDefault();
98	        } catch (NoSuchAlgorithmException e) {
99	            throw new IllegalStateException("No default SSL context is available", e);
100	        }
101	    }
102	
103	    @Override
104	    HttpConnection.Response execute() throws IOException {
105	        try {
106	            HttpRequest.Builder reqBuilder =
107	                HttpRequest.newBuilder(req.url.toURI()).method(req.method.name(), requestBody(req));
108	            if (req.timeout() > 0) reqBuilder.timeout(
109	                Duration.ofMillis(req.timeout())); // infinite if unset (UrlConnection / jsoup uses 0 for same)
110	            CookieUtil.applyCookiesToRequest(req, reqBuilder::header);
111	
112	            // headers:
113	            req.multiHeaders().forEach((key, values) -> {
114	                values.forEach(value -> reqBuilder.header(key, value));
115	            });
116	
117	            if (req.proxy() != null) perRequestProxy.set(req.proxy()); // set up per request proxy
118	            HttpRequest hReq = reqBuilder.build();
119	            HttpClient client = client();
120	            hRes = client.send(hReq, HttpResponse.BodyHandlers.ofInputStream());
121	            HttpHeaders headers = hRes.headers();
122	
123	            // set up the response
124	            Response res = new Response(req);
125	            res.executor = this;
126	            res.method = Connection.Method.valueOf(hRes.request().method());
127	            res.url = hRes.uri().toURL();
128	            res.statusCode = hRes.statusCode();
129	            res.statusMessage = StatusMessage(res.statusCode);
130	            res.contentType = headers.firstValue("content-type").orElse(null);
