/**
 * Resolves the currently bound progress handler. The handler source is read live on every event, so replacing or
 * cancelling the handler mid-response takes effect on the next notification without re-registering. A newly bound
 * handler instance observes independently from the current logical position, without inheriting the previous
 * handler's completion or high-water state.
 */
private @Nullable Handle<?> activeHandle() {
    Supplier<? extends @Nullable Handle<?>> source = progressSource;
    if (source == null) return null;
    Handle<?> handle = source.get();
    if (handle == null) return null; // no handler currently registered (e.g. cancelled after an earlier event)
    if (handle.callback != lastCallback) {
        lastCallback = handle.callback;
        restartProgressObservation(false); // a switched-to handler gets its own counters, but entity facts are kept
    }
    return handle;
}

/**
 * Refreshes the high-water position against the logical read position, and returns the processed value to report:
 * the furthest byte actually delivered, clamped to the declared length. An unknown length is always reported as
 * read. Delivering more bytes than were declared latches {@link #lengthMismatch} so that no completion can later
 * be signalled, while the reported {@code processed} can never exceed the declared value.
 */
private int reportedProcessed() {
    if (readPos > highWater) highWater = readPos;
    int reported = highWater;
    if (contentLength > 0 && reported > contentLength) {
        lengthMismatch = true;
        reported = contentLength;
    }
    return reported;
}

/**
 * Emits the single initial progress event {@code (0, total, 0%)} on the first controlled read. A declared length
 * of zero is an already-complete entity, so its one and only event is the terminal completion.
 */
private void emitInitialProgress() {
    Handle<?> handle = activeHandle();
    if (emittedInitial || handle == null) return;
    if (contentLength == 0) { // empty entity: nothing can ever be read, so complete immediately and exactly once
        complete();
        return;
    }
    emittedInitial = true;
    int processed = reportedProcessed();
    lastEmitted = processed;
    float percent = contentLength > 0 ? Math.min(100f, processed * 100f / contentLength) : 0f;
    deliver(handle, processed, contentLength, percent);
}

/**
 * Emits an intermediate progress event, unless the logical position is being re-read after a reset (or the
 * handler is new to the current position), in which case the already-reported high-water position is held so that
 * progress never moves backwards or repeats at zero.
 */
private void emitProgress() {
    Handle<?> handle = activeHandle();
    if (handle == null) return;
    int processed = reportedProcessed();
    if (processed == lastEmitted) return; // re-reading buffered content after a reset: no new progress
    lastEmitted = processed;
    // calculate percent complete against the declared length; unknown length stays at 0 and total stays -1
    float percent;
    if (contentLength > 0) {
        percent = processed * 100f / contentLength;
        // 100% is reserved for the single terminal event confirmed at end-of-entity; an intermediate read that
        // already meets the declared total (without an end-of-entity confirmation yet) reports just below it
        if (percent >= 100f) percent = Math.nextDown(100f);
    } else {
        percent = 0f;
    }
    deliver(handle, processed, contentLength, percent);
}

/**
 * Delegates a single progress event to the currently bound callback, isolating any {@link RuntimeException} the
 * callback throws. The callback is a side-channel observer: its failure is swallowed for this notification only
 * and neither aborts the read nor forges or suppresses any later event (including the terminal completion), so
 * the handler keeps receiving subsequent notifications and no state leaks to another handler or the next request.
 */
@SuppressWarnings("rawtypes")
private static void deliver(Handle handle, int processed, int total, float percent) {
    try {
        //noinspection unchecked
        handle.callback.onProgress(processed, total, percent, handle.context);
    } catch (RuntimeException e) {
        // this notification only; the network read, resource close, and following notifications all continue
    }
}

/**
 * Emits the exactly-once terminal event once the entity has been confirmed read to its end. The event is a
 * successful {@code 100%} completion only when the response status is successful and the delivered entity
 * exactly matches the declared length; {@code total} is then the declared length, or stays {@code -1} for an
 * unknown length (the delivered byte count is carried in {@code processed}). Reaching a configured cap while
 * further content exists never gets here (that is a truncation), an unsuccessful status or a length mismatch
 * reports only the partial delivery below {@code 100%}, and an I/O failure does not call this at all, so a failed
 * read never reports completion.
 */
private void complete() {
    Handle<?> handle = activeHandle();
    if (handle == null || completed) return;
    completed = true;
    emittedInitial = true;
    if (readPos > highWater) highWater = readPos;
    int actual = highWater;
    boolean mismatch = contentLength > 0 && (lengthMismatch || actual != contentLength);

    if (successful && !mismatch) {
        int processed = contentLength > 0 ? contentLength : actual;
        // an unknown length stays -1 even at the terminal event; processed carries the actual delivered bytes
        deliver(handle, processed, contentLength, 100f);
    } else {
        // unsuccessful status, or the entity did not match its declared length: report the actual partial
        // delivery, but hold below completion and keep the declared total (-1 when unknown) so the caller never
        // mistakes it for a successful completion
        int processed = contentLength > 0 ? Math.min(actual, contentLength) : actual;
        float percent = contentLength > 0
            ? Math.min(Math.nextDown(100f), processed * 100f / contentLength)
            : 0f;
        deliver(handle, processed, contentLength, percent);
    }
}

public <ProgressContext> ControllableInputStream onProgress(int contentLength, Progress<ProgressContext> callback, ProgressContext context) {
    return onProgress(contentLength, true, callback, context);
}

public <ProgressContext> ControllableInputStream onProgress(int contentLength, boolean successful,
    Progress<ProgressContext> callback, ProgressContext context) {
    Validate.notNull(callback);
    Validate.notNull(context);
    return onProgress(contentLength, successful, () -> new Handle<>(callback, context));
}

/**
 * Binds a live source for the active progress handler. The source is re-read for every event, so the handler may
 * be replaced or removed (by returning {@code null}) while the response is being read, and the previously bound
 * handler immediately stops receiving events. Observation state (counters, completion) starts independently for
 * this registration and from the current logical read position.
 */
public ControllableInputStream onProgress(int contentLength, boolean successful,
    Supplier<? extends @Nullable Handle<?>> source) {
    this.contentLength = contentLength;
    this.successful = successful;
    this.progressSource = source;
    lastCallback = null;
    restartProgressObservation(true);
    return this;
}

/** Resets the per-observer progress state, optionally clearing the entity-level length-mismatch fact. */
private void restartProgressObservation(boolean clearMismatch) {
    emittedInitial = false;
    completed = false;
    if (clearMismatch) lengthMismatch = false;
    lastEmitted = -1;
    highWater = readPos;
}

/**
 * Binds a progress callback to the context object it is supplied with on every event.
 */
public static final class Handle<ProgressContext> {
    final Progress<ProgressContext> callback;
    final ProgressContext context;

    public Handle(Progress<ProgressContext> callback, ProgressContext context) {
        this.callback = callback;
        this.context = context;
    }
}

