287	    /**
288	     Emits the single initial progress event {@code (0, total, 0%)} on the first controlled read. A declared length
289	     of zero is an already-complete entity, so its one and only event is the terminal completion.
290	     */
291	    private void emitInitialProgress() {
292	        Handle<?> handle = activeHandle();
293	        if (emittedInitial || handle == null) return;
294	        emittedInitial = true;
295	        if (contentLength == 0) { // a declared-empty entity: nothing can ever be read, so complete exactly once
296	            complete();
297	        } else if (contentLength > 0) {
298	            // a declared length starts with a determinable (0, total, 0%) event
299	            int processed = reportedProcessed();
300	            lastEmitted = processed;
301	            float percent = Math.min(100f, processed * 100f / contentLength);
302	            deliver(handle, processed, contentLength, percent);
303	        }
304	        // an unknown length has no determinable start: hold the initial event until bytes actually arrive (handled in
305	        // emitProgress), so an unknown-length empty entity yields only its single terminal completion
306	    }
307	
308	    /**
309	     Emits an intermediate progress event, unless the logical position is being re-read after a reset, in which case
310	     the already-reported high-water position is held so that progress never moves backwards or repeats.
311	     */
312	    private void emitProgress() {
313	        Handle<?> handle = activeHandle();
314	        if (handle == null) return;
315	        int processed = reportedProcessed();
316	        // an unknown length delays its initial event until bytes actually arrive (so an empty entity has no leading
317	        // 0% event); emit that single (0, -1, 0) before the first data event
318	        if (contentLength < 0 && lastEmitted < 0) {
319	            deliver(handle, 0, contentLength, 0f);
320	            lastEmitted = 0;
321	        }
322	        if (processed == lastEmitted) return; // re-reading buffered content after a reset: no new progress
323	        lastEmitted = processed;
324	        // calculate percent complete against the declared length; for an unknown length both percent stay at 0 and
325	        // total stays -1, right through to the terminal event
326	        float percent;
327	        if (contentLength > 0) {
328	            percent = processed * 100f / contentLength;
329	            // 100% is reserved for the single terminal event confirmed at end-of-entity; an intermediate read that
330	            // already meets the declared total (without an end-of-entity confirmation yet) reports just below it
331	            if (percent >= 100f) percent = Math.nextDown(100f);
332	        } else {
333	            percent = 0f;
334	        }
335	        deliver(handle, processed, contentLength, percent);
336	    }
337	
338	    /**
339	     * Resolves the handler currently bound to this stream, re-reading the live source on every event. If a different
340	     * callback instance is now bound, observation state restarts from the current logical position, so the new handler
341	     * neither inherits the previous handler's high-water/completion nor receives any of its earlier events; a null
342	     * source result means the handler was cancelled and no event is delivered.
343	     */
344	    private @Nullable Handle<?> activeHandle() {
345	        Supplier<? extends @Nullable Handle<?>> source = progressSource;
346	        if (source == null) return null;
347	        Handle<?> handle = source.get();
348	        if (handle == null) return null;
349	        if (handle.callback != lastCallback) {
350	            Object previous = lastCallback;
351	            lastCallback = handle.callback;
352	            restartObservation(false); // entity-level facts (length mismatch) carry over; observer counters do not
353	            if (previous != null) {
354	                // a live switch between two handlers: the event that discovered the newcomer is its first event, so
355	                // anchor it at the current position and suppress a separate (0,...) initial. It then observes from
356	                // where it was bound (no stale 0, no duplicate); the first binding / an explicit re-registration
357	                // leaves emittedInitial false and lastEmitted -1, so the normal initial event still fires.
358	                emittedInitial = true;
359	                lastEmitted = reportedProcessed();
360	            }
361	        }
362	        return handle;
363	    }
