365	    /**
366	     * Reports the processed byte count for an event: the furthest logical position actually delivered (held across a
367	     * mark/reset re-read so progress never walks backwards), clamped to a declared length so {@code processed} can
368	     * never exceed it. Delivering more bytes than were declared latches {@link #lengthMismatch} so no later event can
369	     * signal completion.
370	     */
371	    private int reportedProcessed() {
372	        if (readPos > highWater) highWater = readPos;
373	        int processed = highWater;
374	        if (contentLength > 0 && processed > contentLength) {
375	            lengthMismatch = true;
376	            processed = contentLength;
377	        }
378	        return processed;
379	    }
380	
381	    /**
382	     * Delegates a single progress event to the bound callback, isolating any {@link RuntimeException} it throws. The
383	     * callback is a side-channel observer: its exception is swallowed for this notification only and neither aborts
384	     * the network read, resource close, or parsing, nor suppresses any later notification (including completion), nor
385	     * leaks into another callback or the next request.
386	     */
387	    @SuppressWarnings("rawtypes")
388	    private static void deliver(Handle handle, int processed, int total, float percent) {
389	        try {
390	            //noinspection unchecked
391	            handle.callback.onProgress(processed, total, percent, handle.context);
392	        } catch (RuntimeException e) {
393	            // this notification only; reads, close, and subsequent notifications continue unaffected
394	        }
395	    }
396	
397	    /**
398	     * Emits the terminal event once the entity has been confirmed read to its end. A successful {@code 100%}
399	     * completion is emitted exactly once, only when the status is successful and the delivered entity matches the
400	     * declared length; {@code total} is then the declared length, or stays {@code -1} for an unknown length (the
401	     * actual delivered byte count is carried in {@code processed}). Reaching the configured cap while more content
402	     * exists never gets here (that is a truncation, handled by the caller); an unsuccessful status or a declared
403	     * length that did not match the actual entity reports only the partial delivery below {@code 100%}; an I/O
404	     * failure never calls this, so a failed read never reports completion or looks successful.
405	     */
406	    private void complete() {
407	        Handle<?> handle = activeHandle();
408	        if (handle == null || completed) return;
409	        completed = true;
410	        emittedInitial = true;
411	        if (readPos > highWater) highWater = readPos;
412	        int actual = highWater;
413	        boolean mismatch = contentLength > 0 && (lengthMismatch || actual != contentLength);
414	
415	        if (successful && !mismatch) {
416	            int processed = contentLength > 0 ? contentLength : actual;
417	            // an unknown length stays -1 even at the terminal event; processed carries the delivered byte count
418	            deliver(handle, processed, contentLength, 100f);
419	        } else {
420	            // unsuccessful status, or the entity did not match its declared length: report the bytes actually
421	            // delivered, but hold below completion and keep the declared total (-1 when unknown) so the caller never
422	            // mistakes it for a successful completion
423	            int processed = contentLength > 0 ? Math.min(actual, contentLength) : actual;
424	            float percent = contentLength > 0
425	                ? Math.min(Math.nextDown(100f), processed * 100f / contentLength)
426	                : 0f;
427	            deliver(handle, processed, contentLength, percent);
428	        }
429	    }
